head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Radio > M > getItemCount]<br/>컴포넌트에 정의된 전체 아이템의 갯수를 반환합니다.",
    "validation" : [                
        "name 속성에 의한 그룹 단위가 아닌 컴포넌트 단위로 아이템의 갯수를 반환합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    let properties = {
        name : "radioGroup",        
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createLabel('label="name 속성에 의해 2개의 컴포넌트가 그룹으로 묶인 상태임"', '', 'label1');
    $c.gcm.createBasicRadio(cList);
    $c.gcm.createBasicRadio(cList, '', 'target2');
}



scwin.btn_getItemCount_onclick = function (e) { 
    let rtn = '';

    rtn = target1.getItemCount();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 getItemCount : " + rtn);

    rtn = target2.getItemCount();
    wf_body_bottom.getObj("scwin").setReturnValue("target2 getItemCount : " + rtn);   
};
